from pathlib import Path
import base64, zlib, json

PAYLOAD = ""
parts = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
p = Path("index.html")
s = p.read_text(encoding="utf-8")
if 'id="ch-interactive-revision-css"' in s or 'id="ch-interactive-revision-js"' in s:
    raise SystemExit("Revision already present")
required = ['</head>', '</body>', 'class="vision-map"', 'class="horizon"', 'id="fit"']
missing = [x for x in required if x not in s]
if missing:
    raise SystemExit(f"Required anchors missing: {missing}")
style = '<style id="ch-interactive-revision-css">\n' + parts['css'].strip('\n') + '\n</style>'
script = '<script id="ch-interactive-revision-js">\n' + parts['js'].strip('\n') + '\n</script>'
s = s.replace('</head>', style + '\n</head>', 1)
s = s.replace('</body>', script + '\n</body>', 1)
p.write_text(s, encoding="utf-8")
print("Applied isolated Concord House interactive revision to exact branch source")
